"Burned by a laser beam": "Обожжён лазерным лучом",
"Beams show a dashed line first. Move aside, or dash straight through.": "Лучи сначала показывают пунктир. Отойди в сторону или пройди сквозь рывком.",
"Crushed by the Warden stomp": "Раздавлен топотом Стража",
"The red circle shows where it lands. Leave the circle.": "Красный круг показывает, куда он приземлится. Выйди из круга.",
"Cut down by Kage's dash": "Срублен рывком Каге",
"Dash INTO his red line to clash and stun him.": "Делай рывок В его красную линию, чтобы столкнуться и оглушить его.",
"Hit by the express train": "Сбит экспрессом",
"Red stripes mean a train is coming down that track.": "Красные полосы — по этому пути идёт поезд.",
"Rammed by {0}": "Протаранен: {0}",
"THE BOSS": "БОСС",
"Do not stand next to the boss; strike and bounce away.": "Не стой рядом с боссом: ударь и отскочи.",
"Fried by Raijin's lightning curtain": "Сожжён занавесом молний Райдзина",
"Go through the green gap, or dash straight through the wall.": "Проходи через зелёный просвет или прорвись сквозь стену рывком.",
"Struck by Raijin's lightning": "Поражён молнией Райдзина",
"Each drum marks a blue circle on you. Keep moving, and break the drums.": "Каждый барабан отмечает на тебе синий круг. Двигайся и разбивай барабаны.",
"Show every tip again": "Показать все подсказки снова",
"RESET": "СБРОС",
"DONE": "ГОТОВО",
"Assist runs still count for the story, but not for leaderboards or ghosts.": "Забеги с помощью засчитываются в сюжете, но не в таблицах лидеров и призраках.",
"Stats are only where players fail or quit, so the game can be balanced. No names, no messages.": "Статистика собирается только о том, где игроки проигрывают или выходят, чтобы сбалансировать игру. Без имён и сообщений.",
