"MEDIC DRONE": "ДРОН-МЕДИК",
"Its green beam heals an enemy and gives it a shield. Cut the medic first.": "Его зелёный луч лечит врага и даёт ему щит. Сначала руби медика.",
"It copies your last dash a moment later. The pink line shows where it will go: step off it.": "Повторяет твой последний рывок чуть позже. Розовая линия показывает его путь: сойди с неё.",
"Dashing into the bright arc bounces you away. Hit the dark side, or use the bounce for a ricochet crit.": "Рывок в яркую дугу отбрасывает тебя назад. Бей по тёмной стороне или используй отскок для крита рикошетом.",
"PROXIMITY MINE": "МИНА-ЛОВУШКА",
"Walking near it sets it off. Dash straight through it to disarm it for points.": "Если подойти близко, она взорвётся. Пройди сквозь неё рывком, чтобы обезвредить и получить очки.",
"MINI-BOSS": "МИНИ-БОСС",
"A tough enemy with its own attacks and a health bar. Learn its warning sign, then strike.": "Сильный враг со своими атаками и полоской здоровья. Выучи его сигнал, затем бей.",
"Mini-boss on the roof! Learn its pattern.": "Мини-босс на крыше! Изучи его паттерн.",
"Big one incoming. Wait for the opening.": "Идёт здоровяк. Жди момента.",
"Mini-boss down! Great work.": "Мини-босс повержен! Отличная работа.",
"That one hit hard. Nice.": "Этот бил больно. Хорошо сработано.",
"The mimic repeats your dash along the pink line. Step off the line after you dash.": "Подражатель повторяет твой рывок по розовой линии. После рывка сойди с линии.",
"The red line is its charge. Step aside and let it hit the wall: that stuns it and drops its shield.": "Красная линия — его таран. Отойди и дай ему врезаться в стену: это оглушит его и снимет щит.",
"The wraith fades before it blinks next to you. Keep moving when it fades.": "Призрак тает, прежде чем появиться рядом. Двигайся, когда он тает.",
"Blown up by a mine": "Подорвался на мине",
"Do not walk near mines. Dash straight through a mine to disarm it.": "Не подходи к минам. Пройди сквозь мину рывком, чтобы обезвредить её.",
"Shot by the {0}": "Подстрелен: {0}",
"Mini-bosses fire in patterns. Find the gap in the pattern, and slash the slow shots back.": "Мини-боссы стреляют узорами. Найди просвет в узоре и отбивай медленные выстрелы.",
"SHADOW KUNAI": "ТЕНЕВЫЕ КУНАИ",
"Every dash also throws 3 kunai in a fan.": "Каждый рывок ещё и метает веер из 3 кунаев.",
"CHAIN WHIP": "ЦЕПНОЙ КНУТ",
"When a dash ends, the chain cracks a wide arc in front of you.": "В конце рывка цепь хлещет широкой дугой перед тобой.",
"PLASMA SPEAR": "ПЛАЗМЕННОЕ КОПЬЁ",
"Fast and long. Pierces shields, bubbles and mirrors, and never bounces back.": "Быстрое и длинное. Пробивает щиты, пузыри и зеркала и никогда не отскакивает.",
"TITAN GAUNTLETS": "ТИТАНОВЫЕ ПЕРЧАТКИ",
"Short, heavy punches that launch enemies into walls and each other.": "Короткие тяжёлые удары, отбрасывающие врагов в стены и друг в друга.",
"SHADOW RAIN": "ТЕНЕВОЙ ДОЖДЬ",
