"Fast little skitter-bot that rams you. Cheap, but they come in swarms. Slash them before they touch you.": "Быстрый маленький бот-попрыгунчик, таранит тебя. Слабый, но ходит роем. Руби, пока не коснулся.",
"Keeps its distance and aims with an orange laser before it fires. Step off the line, or parry the shot back.": "Держит дистанцию и перед выстрелом целится оранжевым лазером. Сойди с линии или отбей выстрел.",
"A green shield blocks hits from the front. Bounce off a rail first, hit it from behind, or break it with a perfect parry.": "Зелёный щит блокирует удары спереди. Сначала отскочи от ограждения, бей сзади или сломай щит идеальным парированием.",
"Rushes you and blinks before it explodes. Slash it early or get out of the ring.": "Мчится к тебе и мигает перед взрывом. Руби заранее или выходи из кольца.",
"Circles you and spins out rings of bullets. Dash through the gaps and parry what you can.": "Кружит вокруг и выпускает кольца пуль. Проходи рывком сквозь просветы и отбивай, что можешь.",
"Fades out and reappears right next to you. Watch for the shimmer and strike first.": "Исчезает и появляется прямо рядом с тобой. Следи за мерцанием и бей первым.",
"Splits into two minis when it dies. Save a dash for the pieces.": "После смерти делится на двух мини. Оставь рывок для осколков.",
"The small half of a splitter. Weak, but quick.": "Маленькая половинка делителя. Слабая, но быстрая.",
"Tethers its friends to give them shield bubbles. Cut the warden first and the bubbles fall.": "Связывает союзников, давая им пузыри-щиты. Сначала руби стража — и пузыри исчезнут.",
"Heals the most hurt enemy nearby and gives it a shield. Always cut the medic first.": "Лечит самого раненого врага рядом и даёт ему щит. Всегда руби медика первым.",
"Copies your last dash a moment later. The pink line shows where it will go: step off it.": "Повторяет твой последний рывок чуть позже. Розовая линия показывает его путь: сойди с неё.",
"Circles at mid range and drops proximity mines. Dash straight through a mine to disarm it.": "Кружит на средней дистанции и бросает мины. Пройди сквозь мину рывком, чтобы обезвредить её.",
"Its bright arc bounces your dash away. Hit the dark side, or use the bounce for a ricochet crit.": "Его яркая дуга отбивает твой рывок. Бей по тёмной стороне или используй отскок для крита рикошетом.",
"Carries stolen data and blinks to a far corner every time you hit it. Keep chasing before the timer runs out.": "Несёт украденные данные и при каждом попадании телепортируется в дальний угол. Продолжай погоню, пока не вышло время.",
"A golden drone full of credits that runs away. Catch it before it escapes for a jackpot.": "Золотой дрон, полный кредитов, который убегает. Поймай его, пока не скрылся, — и сорвёшь джекпот.",
"A shadow clone of Kage. It dashes along a red line after a short warning.": "Теневой клон Каге. После короткого предупреждения делает рывок по красной линии.",
"Mini-boss. A front shield and a charge along a red line. Step aside and let it hit the wall: that stuns it and drops the shield.": "Мини-босс. Щит спереди и таран по красной линии. Отойди и дай ему врезаться в стену: это оглушит его и снимет щит.",
"Mini-boss. A slow walking tank that fires fans of bullets and drops mines. Stay close to its flank.": "Мини-босс. Медленный шагающий танк, стреляет веерами пуль и бросает мины. Держись у его бока.",
"Mini-boss. Spirals bullets, fades out, then blinks next to you with a ring of shots. Keep moving when it fades.": "Мини-босс. Пускает спирали пуль, исчезает, затем появляется рядом с кольцом выстрелов. Двигайся, когда он тает.",
"A train security mech. Cut its weapon arms, then slash the gold weakpoint arc to stagger it.": "Робот охраны поезда. Отруби ему оружейные руки, затем бей по золотой дуге слабого места, чтобы оглушить.",
"A three-headed gunship. Destroy the heads to drop its shield, then go for the core.": "Трёхглавый ганшип. Уничтожь головы, чтобы снять щит, затем атакуй ядро.",
"The shadow ronin. Dash into his red line to clash and stun him, then strike.": "Теневой ронин. Сделай рывок в его красную линию, чтобы столкнуться и оглушить, затем бей.",
"The rogue transit AI. Break the firewall nodes, then survive the glitch storm.": "Вышедший из-под контроля ИИ транспорта. Сломай узлы файрвола, затем переживи шторм сбоев.",
"The storm god of the orbital ring. Break the thunder drums and find the gap in the lightning curtain.": "Бог бури с орбитального кольца. Разбей громовые барабаны и найди просвет в занавесе молний.",
"Season reward: claim it on the SEASON screen ({0}).": "Награда сезона: забери её на экране СЕЗОН ({0}).",
