"SAVE PHOTO": "СОХРАНИТЬ ФОТО",
"Tap the picture to hide the controls. Drag it to move it when zoomed in.": "Коснись картинки, чтобы скрыть кнопки. При увеличении перетаскивай её.",
"Pause or play": "Пауза или воспроизведение",
