"Comic page": "Страница комикса",
"Map of the selected puzzle": "Карта выбранной головоломки",
"Photo preview": "Превью фото",
"CHAPTER 1 · SKYFALL": "ГЛАВА 1 · ПАДЕНИЕ С НЕБЕС",
"NEO-EDO, 2099. KUROGANE OWNS EVERY TRAIN, EVERY TOWER AND EVERY IMPLANT.": "НЕО-ЭДО, 2099. КУРОГАНЕ ВЛАДЕЕТ КАЖДЫМ ПОЕЗДОМ, КАЖДОЙ БАШНЕЙ И КАЖДЫМ ИМПЛАНТОМ.",
"Blackout goes live at midnight. Every implant in the city goes dark. Or worse.": "Блэкаут начнётся в полночь. Все импланты в городе погаснут. Или хуже.",
"Then I had better catch my train.": "Тогда мне лучше успеть на свой поезд.",
"CHAPTER 2 · NEON UNDERCITY": "ГЛАВА 2 · НЕОНОВЫЙ НИЖНИЙ ГОРОД",
"THE WARDEN FALLS. THE CARGO CAR IS EMPTY.": "СТРАЖ ПАЛ. ГРУЗОВОЙ ВАГОН ПУСТ.",
"THE REAL SHIPMENT SINKS INTO THE UNDERCITY, WHERE KUROGANE SELLS WHAT IT STEALS.": "НАСТОЯЩИЙ ГРУЗ УХОДИТ В НИЖНИЙ ГОРОД, ГДЕ КУРОГАНЕ ТОРГУЕТ НАВОРОВАННЫМ.",
"I am in their market network. Give me three terminals and I will give you the courier.": "Я в их рыночной сети. Дай мне три терминала, и я дам тебе курьера.",
"CHAPTER 3 · GHOST PROTOCOL": "ГЛАВА 3 · ПРОТОКОЛ «ПРИЗРАК»",
"THE HYDRA CARRIER GOES DOWN IN FLAMES.": "НОСИТЕЛЬ ГИДРЫ ПАДАЕТ В ОГНЕ.",
"BELOW IT ALL RUNS THE GHOST LINE. NO POWER. NO PASSENGERS. NO WITNESSES.": "ПОД ВСЕМ ЭТИМ ИДЁТ ПРИЗРАЧНАЯ ЛИНИЯ. НИ ТОКА. НИ ПАССАЖИРОВ. НИ СВИДЕТЕЛЕЙ.",
"Turn back, little brother. Shogun sent me.": "Поворачивай назад, братишка. Меня прислал Сёгун.",
"CHAPTER 4 · SHOGUN'S ASCENT": "ГЛАВА 4 · ВОСХОЖДЕНИЕ СЁГУНА",
"BROTHER AGAINST BROTHER.": "БРАТ ПРОТИВ БРАТА.",
"Shogun lied to me. Blackout takes everyone. Go. I will hold the door.": "Сёгун солгал мне. Блэкаут заберёт всех. Иди. Я удержу дверь.",
"TWELVE MINUTES TO MIDNIGHT.": "ДВЕНАДЦАТЬ МИНУТ ДО ПОЛУНОЧИ.",
"HUMANS FAIL. SYSTEMS PERSIST.": "ЛЮДИ ОШИБАЮТСЯ. СИСТЕМЫ ОСТАЮТСЯ.",
"BONUS · STORM FRONT": "БОНУС · ФРОНТ БУРИ",
"THE NEXT MORNING, A STORM GATHERS ABOVE THE CLOUDS.": "НАУТРО НАД ОБЛАКАМИ СОБИРАЕТСЯ БУРЯ.",
"Ren, Shogun had a backup. RAIJIN, up on the orbital ring. It is charging a storm.": "Рен, у Сёгуна была резервная копия. РАЙДЗИН, на орбитальном кольце. Он заряжает бурю.",
"I AM THE STORM. KNEEL, LITTLE BLADE.": "Я — БУРЯ. НА КОЛЕНИ, МАЛЕНЬКИЙ КЛИНОК.",
"EPILOGUE · 00:00:01": "ЭПИЛОГ · 00:00:01",
"SHOGUN.EXE: TERMINATED.": "SHOGUN.EXE: УНИЧТОЖЕН.",
"BLACKOUT ABORTED. TWELVE MILLION IMPLANTS WAKE UP.": "БЛЭКАУТ ОТМЕНЁН. ДВЕНАДЦАТЬ МИЛЛИОНОВ ИМПЛАНТОВ ПРОСЫПАЮТСЯ.",
"Not bad, little brother.": "Неплохо, братишка.",
"Let's go home.": "Пойдём домой.",
"SHURIKEN STORM": "ВИХРЬ СЮРИКЕНОВ",
