"Start with the story. New modes open as you play.": "Начни с сюжета. Новые режимы открываются по ходу игры.",
"Clear stage {0} to open:": "Пройди этап {0}, чтобы открыть:",
"DAILY BONUS · DAY {0}/7": "ЕЖЕДНЕВНЫЙ БОНУС · ДЕНЬ {0}/7",
