"{0} SEASON XP": "{0} XP СЕЗОНА",
"DAILY BONUS +{0} CR": "ЕЖЕДНЕВНЫЙ БОНУС +{0} CR",
"Come back every day: day 7 pays the most.": "Заходи каждый день: 7-й день платит больше всего.",
"INVITE REWARD: NEON TWINS +{0} CR": "НАГРАДА ЗА ПРИГЛАШЕНИЕ: НЕОНОВЫЕ БЛИЗНЕЦЫ +{0} CR",
"FRIEND REWARD: NEON TWINS +{0} CR": "НАГРАДА ЗА ДРУГА: НЕОНОВЫЕ БЛИЗНЕЦЫ +{0} CR",
"THIS WEEK": "ЭТА НЕДЕЛЯ",
"Loading crews…": "Загружаем команды…",
"Crews did not load. Check your connection and try again.": "Команды не загрузились. Проверь соединение и попробуй снова.",
"A crew adds up its members' WEEKLY scores. Play the weekly challenge to push your crew up the table.": "Команда складывает НЕДЕЛЬНЫЕ очки своих участников. Играй в недельное испытание, чтобы поднять команду в таблице.",
"#{0} of {1} crews · {2} points this week · {3}/{4} members": "№{0} из {1} команд · {2} очков за неделю · {3}/{4} участников",
