"The enemy that breaks your shields remembers you. It gets a name and comes back in later runs, stronger every time it wins. Slay it for a big bounty.": "Враг, пробивший твои щиты, тебя запоминает. Он получает имя и возвращается в следующих забегах, сильнее с каждой победой. Победи его ради большой награды.",
"Your own loft: a rack with every blade you own, a trophy statue for every boss you beat, an arcade cabinet, a WANTED poster for your nemesis, and your pet wandering around.": "Твой собственный лофт: стойка со всеми клинками, статуэтка за каждого побеждённого босса, игровой автомат, плакат «Разыскивается» с твоим немезисом и гуляющий питомец.",
