"LANTERN ONI": "ФОНАРНЫЙ ОНИ",
"The parade leader's colors: lantern orange and night black. Defeat HYAKKI to claim it.": "Цвета вожака парада: фонарный оранжевый и ночной чёрный. Победите HYAKKI, чтобы получить его.",
"Defeat HYAKKI in chapter 20": "Победите HYAKKI в главе 20",
"EX FRAME": "EX-КАРКАС",
"A black war frame with a red EX core. Beat every EX boss to claim it.": "Чёрный боевой каркас с красным EX-ядром. Победите всех EX-боссов, чтобы получить его.",
"Beat every EX boss in the SECRETS chapter": "Победите всех EX-боссов в главе ТАЙНЫ",
"PUMPKIN KING": "КОРОЛЬ ТЫКВ",
"A jack-o-lantern head with a burning grin and a tattered cape. NEON HALLOWEEN event reward.": "Голова-тыква с горящей ухмылкой и рваный плащ. Награда события НЕОНОВЫЙ ХЭЛЛОУИН.",
"NEON HALLOWEEN": "НЕОНОВЫЙ ХЭЛЛОУИН",
"Event reward: get it in the {0} event": "Награда события: получите её в событии {0}",
"NEON YETI": "НЕОНОВЫЙ ЙЕТИ",
"A shaggy snow beast with ice horns and glowing eyes. FROSTBYTE WINTER event reward.": "Косматый снежный зверь с ледяными рогами и светящимися глазами. Награда события МОРОЗНАЯ ЗИМА.",
"EX EDGE": "EX-ЛЕЗВИЕ",
"A red-hot blade with a white edge. Beat three EX bosses to claim it.": "Раскалённый клинок с белой кромкой. Победите трёх EX-боссов, чтобы получить его.",
"Beat three EX bosses in the SECRETS chapter": "Победите трёх EX-боссов в главе ТАЙНЫ",
"CANDY CORN": "КОНФЕТНАЯ КУКУРУЗА",
"Orange, yellow and white stripes. Kills burst into candy. NEON HALLOWEEN event reward.": "Оранжевые, жёлтые и белые полосы. Враги взрываются конфетами. Награда события НЕОНОВЫЙ ХЭЛЛОУИН.",
"FROSTBITE": "ОБМОРОЖЕНИЕ",
"Snowflakes spin along the blade. Kills burst into a snow cloud. FROSTBYTE WINTER event reward.": "Снежинки кружатся вдоль клинка. Враги взрываются снежным облаком. Награда события МОРОЗНАЯ ЗИМА.",
"BATLING": "НЕТОПЫРЬ",
"Neon bat": "Неоновая летучая мышь",
"A tiny neon bat. Every 7 seconds it screeches and stuns the two enemies nearest to you. NEON HALLOWEEN event reward.": "Крошечная неоновая летучая мышь. Каждые 7 секунд визжит и оглушает двух ближайших врагов. Награда события НЕОНОВЫЙ ХЭЛЛОУИН.",
"PENGUIN BOT": "ПИНГВИН-БОТ",
"Ice slider": "Ледяной скользун",
"A round robot penguin. Every 9 seconds it belly-slides through an enemy and freezes it. FROSTBYTE WINTER event reward.": "Круглый пингвин-робот. Каждые 9 секунд проезжает на брюхе сквозь врага и замораживает его. Награда события МОРОЗНАЯ ЗИМА.",
"SCREECH!": "ВИЗГ!",
"The night parade takes over the maglev line. Enemies come in costume, and every 6th kill leaves a JACK-O-BOMB that blows up the enemies around it.": "Ночной парад захватывает линию маглева. Враги приходят в костюмах, а каждое 6-е убийство оставляет ТЫКВОБОМБУ, которая взрывает врагов вокруг.",
"CANDY": "КОНФЕТЫ",
"Snow on every rooftop. Enemies wear Santa hats and scarves, and every 3rd dash throws a SNOWBALL that freezes what it hits.": "Снег на каждой крыше. Враги в шапках Санты и шарфах, а каждый 3-й рывок бросает СНЕЖОК, который замораживает цель.",
"SNOWFLAKES": "СНЕЖИНКИ",
"EVENT REWARDS": "НАГРАДЫ СОБЫТИЯ",
"PLAY THE EVENT": "ИГРАТЬ В СОБЫТИЕ",
"Event rewards are yours to keep after the event ends.": "Награды события остаются у вас и после его окончания.",
"The event is over. See you at the next one!": "Событие закончилось. До встречи на следующем!",
