"WORLD-EATER": "ПОЖИРАТЕЛЬ МИРОВ",
"A relic cleaver rebuilt from the World Boss. Restore three broken pieces.": "Реликтовый тесак, собранный из Босса мира. Восстанови три сломанных части.",
"Worn by the World Boss itself. A very rare World Boss drop.": "Его носит сам Босс мира. Очень редкий дроп с Босса мира.",
