"Open now until Sunday. Much more health. Fight it with your hero.": "Открыт до воскресенья. Намного больше здоровья. Сражайся своим героем.",
"Opens on Thursday. Thursday to Sunday every week.": "Открывается в четверг. С четверга по воскресенье каждую неделю.",
